def merge_sorted(a, b):
  result, i, j = [], 0, 0
  while i < len(a) and j < len(b):
  if a[i] <= b[j]:
  result.append(a[i]); i += 1
  else:
  result.append(b[j]); j += 1
  return result + a[i:] + b[j:]

 print(merge_sorted([1,3,5],[2,4,6]))
 # Output: [1, 2, 3, 4, 5, 6]

def pairs_with_sum(lst, target):
  seen, pairs = set(), []
  for n in lst:
  complement = target - n
  if complement in seen:
  pairs.append((complement, n))
  seen.add(n)
  return pairs

 print(pairs_with_sum([1,2,3,4,5,6], 7))
 # Output: [(3, 4), (2, 5), (1, 6)]

