def flatten_dict(d, parent='', sep='.'):
  items = {}
  for k, v in d.items():
  new_key = f'{parent}{sep}{k}' if parent else k
  if isinstance(v, dict):
  items.update(flatten_dict(v, new_key, sep))
  else:
  items[new_key] = v
  return items

