import random
 def guessing_game(secret=None, max_tries=5):
  if secret is None:
  secret = random.randint(1, 20)
  tries = 0
  while tries < max_tries:
  guess = secret - (max_tries - tries - 1) # Simulate guesses
  tries += 1
  print(f'Guess {tries}: {guess}')
  if guess == secret:
  print(f'Correct! Found in {tries} tries')
  break
  else:
  print(f'Game over! The number was {secret}')

 guessing_game(secret=10)
 # Output: demonstrates loop with break and else

import time
 from functools import wraps

 def timer(func):
  @wraps(func)
  def wrapper(*args, **kwargs):
  start = time.time()
  result = func(*args, **kwargs)
  end = time.time()
  print(f'{func.__name__} took {end-start:.4f}s')
  return result
  return wrapper

 @timer
 def slow_sum(n):
  return sum(range(n))

 print(slow_sum(1000000))
 # Output: slow_sum took ~Xs, 499999500000

