def memoize(func):
  cache = {}
  def wrapper(*args):
  if args not in cache:
  cache[args] = func(*args)
  return cache[args]
  return wrapper

 @memoize
 def factorial(n):
  return 1 if n <= 1 else n * factorial(n-1)

