def bubble_sort(arr):
  n = len(arr)
  for i in range(n):
  for j in range(n-i-1):
  if arr[j] > arr[j+1]:
  arr[j], arr[j+1] = arr[j+1], arr[j]
  return arr

 print(bubble_sort([64,34,25,12,22,11,90]))
 # Output: [11, 12, 22, 25, 34, 64, 90]

class QueueWithStacks:
  def __init__(self): self.s1, self.s2 = [], []
  def enqueue(self, x): self.s1.append(x)
  def dequeue(self):
  if not self.s2:
  while self.s1: self.s2.append(self.s1.pop())
  return self.s2.pop() if self.s2 else None

 q = QueueWithStacks()
 for x in [1,2,3,4]: q.enqueue(x)
 print(q.dequeue()) # 1
 print(q.dequeue()) # 2
 q.enqueue(5)
 print(q.dequeue()) # 3

import json

 def parse_json(text):
  try:
  data = json.loads(text)
  if not isinstance(data, dict):
  raise ValueError('Expected a JSON object')
  required = ['name', 'age']
  for field in required:
  if field not in data:
  raise ValueError(f'Missing required field: {field}')
  return data
  except json.JSONDecodeError as e:
  return f'JSON Error: {e}'
  except ValueError as e:
  return f'Validation Error: {e}'

 print(parse_json('{"name": "Alice", "age": 25}'))
 print(parse_json('{"name": "Bob"}'))
 print(parse_json('not json'))
 # Output: dict, Validation Error, JSON Error

class Node:
  def __init__(self, val): self.val=val; self.left=self.right=None

 class BST:
  def __init__(self): self.root = None
  def insert(self, val):
  def _insert(node, val):
  if not node: return Node(val)
  if val < node.val: node.left = _insert(node.left, val)
  else: node.right = _insert(node.right, val)
  return node
  self.root = _insert(self.root, val)
  def inorder(self):
  result = []
  def _inorder(node):
  if node: _inorder(node.left); result.append(node.val); _inorder(node.right)
  _inorder(self.root); return result

 bst = BST()
 for v in [5,3,7,1,4,6,8]: bst.insert(v)
 print(bst.inorder())
 # Output: [1, 3, 4, 5, 6, 7, 8]

from collections import OrderedDict

 class LRUCache:
  def __init__(self, capacity):
  self.cap = capacity
  self.cache = OrderedDict()
  def get(self, key):
  if key not in self.cache: return -1
  self.cache.move_to_end(key)
  return self.cache[key]
  def put(self, key, value):
  if key in self.cache: self.cache.move_to_end(key)
  self.cache[key] = value
  if len(self.cache) > self.cap: self.cache.popitem(last=False)

 lru = LRUCache(3)
 lru.put(1,1); lru.put(2,2); lru.put(3,3)
 print(lru.get(1)) # 1
 lru.put(4,4) # evicts 2
 print(lru.get(2)) # -1

def lcs(s1, s2):
  m, n = len(s1), len(s2)
  dp = [[0]*(n+1) for _ in range(m+1)]
  for i in range(1,m+1):
  for j in range(1,n+1):
  if s1[i-1]==s2[j-1]: dp[i][j] = dp[i-1][j-1]+1
  else: dp[i][j] = max(dp[i-1][j], dp[i][j-1])
  length = dp[m][n]
  # Reconstruct
  res, i, j = [], m, n
  while i>0 and j>0:
  if s1[i-1]==s2[j-1]: res.append(s1[i-1]); i-=1; j-=1
  elif dp[i-1][j]>dp[i][j-1]: i-=1
  else: j-=1
  return ''.join(reversed(res))

 print(lcs('ABCBDAB','BDCAB'))
 # Output: BCAB or BDAB (length 4)

def validate_types(*types):
  def decorator(func):
  def wrapper(*args, **kwargs):
  for arg, expected_type in zip(args, types):
  if not isinstance(arg, expected_type):
  raise TypeError(f'Expected {expected_type.__name__}, got {type(arg).__name__}')
  return func(*args, **kwargs)
  return wrapper
  return decorator

 @validate_types(str, int)
 def greet(name, times):
  return (f'Hello {name}! ' * times).strip()

 print(greet('Alice', 3))
 try: greet(123, 'Alice')
 except TypeError as e: print(f'Error: {e}')
 # Output: Hello Alice! Hello Alice! Hello Alice!, Error: ...

class Circle:
  def __init__(self, radius):
  self._radius = radius

  @property
  def radius(self): return self._radius

  @radius.setter
  def radius(self, value):
  if value < 0: raise ValueError('Radius cannot be negative')
  self._radius = value

  @property
  def area(self):
  import math
  return math.pi * self._radius ** 2

 c = Circle(5)
 print(f'Radius: {c.radius}, Area: {c.area:.2f}')
 c.radius = 10
 print(f'New Area: {c.area:.2f}')
 # Output: Radius: 5, Area: 78.54; New Area: 314.16

class EventSystem:
  def __init__(self): self.handlers = {}
  def on(self, event, handler): self.handlers.setdefault(event, []).append(handler)
  def emit(self, event, *args):
  for handler in self.handlers.get(event, []):
  handler(*args)

 events = EventSystem()
 events.on('login', lambda u: print(f'{u} logged in'))
 events.on('login', lambda u: print(f'Welcome, {u}!'))
 events.on('logout', lambda u: print(f'{u} logged out'))

 events.emit('login', 'Alice')
 events.emit('logout', 'Alice')
 # Output: Alice logged in, Welcome Alice!, Alice logged out

from collections import defaultdict

 class PubSub:
  def __init__(self): self.subscribers = defaultdict(list)
  def subscribe(self, topic, callback): self.subscribers[topic].append(callback)
  def publish(self, topic, data):
  print(f'Publishing to {topic}: {data}')
  for callback in self.subscribers[topic]:
  callback(data)

 ps = PubSub()
 ps.subscribe('news', lambda x: print(f' Reader 1: {x}'))
 ps.subscribe('news', lambda x: print(f' Reader 2: {x[::-1]}'))
 ps.publish('news', 'Hello World')
 # Output: Publishing..., Reader 1: Hello World, Reader 2: dlroW olleH

class FlexObject:
  def __init__(self):
  object.__setattr__(self, '_data', {})

  def __getattr__(self, name):
  if name in self._data:
  return self._data[name]
  raise AttributeError(f'No attribute: {name}')

  def __setattr__(self, name, value):
  self._data[name] = value

 obj = FlexObject()
 obj.name = 'Alice'
 obj.score = 95
 print(obj.name, obj.score)
 try: print(obj.missing)
 except AttributeError as e: print(e)
 # Output: Alice 95, No attribute: missing

def make_record(typename, fields):
  def __init__(self, *args):
  for name, val in zip(fields, args): setattr(self, name, val)
  def __repr__(self):
  vals = ', '.join(f'{f}={getattr(self,f)!r}' for f in fields)
  return f'{typename}({vals})'
  return type(typename, (), {'__init__': __init__, '__repr__': __repr__})

 Point = make_record('Point', ['x', 'y'])
 Student = make_record('Student', ['name', 'score'])

 p = Point(3, 4)
 print(p)
 s = Student('Alice', 95)
 print(s)
 # Output: Point(x=3, y=4), Student(name='Alice', score=95)

def generate_numbers(n): yield from range(n)
 def filter_even(nums): return (x for x in nums if x%2==0)
 def square(nums): return (x**2 for x in nums)
 def take(nums, n): return (x for _, x in zip(range(n), nums))

 # Create a processing pipeline
 stream = generate_numbers(100)
 stream = filter_even(stream)
 stream = square(stream)
 result = list(take(stream, 5))
 print(result)
 # Output: [0, 4, 16, 36, 64] (squares of first 5 even numbers)

class JSONMixin:
  def to_json(self):
  import json
  return json.dumps(self.__dict__)

 class ReprMixin:
  def __repr__(self):
  attrs = ', '.join(f'{k}={v!r}' for k,v in self.__dict__.items())
  return f'{type(self).__name__}({attrs})'

 class Student(JSONMixin, ReprMixin):
  def __init__(self, name, score):
  self.name = name
  self.score = score

 s = Student('Alice', 95)
 print(repr(s))
 print(s.to_json())
 # Output:
 # Student(name='Alice', score=95)
 # {"name": "Alice", "score": 95}

class StateMachine:
  def __init__(self, initial): self.state = initial; self.log = [initial]
  def transition(self, transitions):
  action = transitions.get(self.state)
  if action: self.state = action; self.log.append(self.state)
  else: raise ValueError(f'No transition from {self.state}')
  return self

 traffic_light = StateMachine('RED')
 for _ in range(6):
  traffic_light.transition({'RED':'GREEN','GREEN':'YELLOW','YELLOW':'RED'})
 print(traffic_light.log)
 # Output: ['RED', 'GREEN', 'YELLOW', 'RED', 'GREEN', 'YELLOW', 'RED']

import pandas as pd
 import numpy as np
 df = pd.DataFrame({'age': [25,30,28,200,26,29], 'salary': [50000,60000,55000,52000,1000000,48000], 'score': [85,90,88,92,78,500]})
 def detect_outliers_iqr(df, cols):
  outlier_summary = {}
  for col in cols:
  Q1, Q3 = df[col].quantile(0.25), df[col].quantile(0.75)
  IQR = Q3 - Q1
  mask = (df[col] < Q1 - 1.5*IQR) | (df[col] > Q3 + 1.5*IQR)
  outlier_summary[col] = mask.sum()
  return pd.Series(outlier_summary)
 print(detect_outliers_iqr(df, ['age','salary','score']))
 # Output: age: 1, salary: 1, score: 1

